import{_ as l,C as r,o as s,c as i,a5 as a,E as n}from"./chunks/framework.BF53ZjCA.js";const f=JSON.parse('{"title":"花式切工","description":"","frontmatter":{"title":"花式切工","cutting":"fancy-cuts"},"headers":[],"relativePath":"zh/cutting/fancy-cuts.md","filePath":"zh/cutting/fancy-cuts.md","lastUpdated":1790876393000}'),o={name:"zh/cutting/fancy-cuts.md"};function c(d,e,h,u,_,m){const t=r("FancyCutGrid");return s(),i("div",null,[e[0]||(e[0]=a('<h1 id="花式切工" tabindex="-1">花式切工 <a class="header-anchor" href="#花式切工" aria-label="Permalink to &quot;花式切工&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>非圆明亮式的异形、阶梯式与改良明亮式切工通常归入花式切工——公主方、祖母绿切、梨形、 椭圆形、马眼形、心形、祖母绿阶梯切等。每种依原石形状、内含物 位置与审美偏好而选。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-fancy-cuts-zh"><p class="gem-identification-boundary__eyebrow">CUTTING BOUNDARY</p><h2 id="identification-boundary-fancy-cuts-zh">边界与安全</h2><p>本页用于比较轮廓与刻面风格的常见取舍；花式切工的名称、比例和市场评价会随 品种与语境变化，不能据此保证视觉效果、价格或成品等级。 </p></aside><h2 id="轮廓速览" tabindex="-1">轮廓速览 <a class="header-anchor" href="#轮廓速览" aria-label="Permalink to &quot;轮廓速览&quot;">​</a></h2>',5)),n(t,{locale:"zh"}),e[1]||(e[1]=a('<h2 id="案例流程" tabindex="-1">案例流程 <a class="header-anchor" href="#案例流程" aria-label="Permalink to &quot;案例流程&quot;">​</a></h2><blockquote><p>教学案例（演示）：异形轮廓的价值判断不能由轮廓名称单独推出。</p></blockquote><h3 id="_1-明确目标" tabindex="-1">1. 明确目标 <a class="header-anchor" href="#_1-明确目标" aria-label="Permalink to &quot;1. 明确目标&quot;">​</a></h3><p>先写清楚目标是最大化原石利用、突出轮廓、降低尖角风险，还是改善视觉表现；目标不同， 对长宽比、尖角处理和损耗的容忍度就不同。</p><h3 id="_2-对照轮廓与刻面" tabindex="-1">2. 对照轮廓与刻面 <a class="header-anchor" href="#_2-对照轮廓与刻面" aria-label="Permalink to &quot;2. 对照轮廓与刻面&quot;">​</a></h3><p>以同一原石分别比较梨形、马眼形或祖母绿阶梯式等候选，记录长宽比、对称性、尖角、 阶梯/明亮刻面组织和可能的蝴蝶结暗区。轮廓只是入口，不能代替比例与抛光检查。</p><h3 id="_3-进行视觉复核" tabindex="-1">3. 进行视觉复核 <a class="header-anchor" href="#_3-进行视觉复核" aria-label="Permalink to &quot;3. 进行视觉复核&quot;">​</a></h3><p>统一旋转样品和光源，观察明暗是否均匀、尖端是否过薄、左右是否失衡；把不同角度看到的 结果分别记录，避免用一个角度代表全部表现。</p><h3 id="_4-停止条件" tabindex="-1">4. 停止条件 <a class="header-anchor" href="#_4-停止条件" aria-label="Permalink to &quot;4. 停止条件&quot;">​</a></h3><p>如果蝴蝶结、尖角耐久性或对称性无法在当前资料下判断，就保留多个方案，不把“更好看” 写成确定结论，也不直接推导价格。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>公主方 (princess)：方形，保留圆明亮火彩，现代婚戒主流。</li><li>祖母绿切 (emerald)：阶梯式刻面，突出净度——适合高净度大石。</li><li>梨形/马眼/心形：异形轮廓，需冠亭比例对称避免&quot;蝴蝶结效应&quot;。</li><li>切工质量、轮廓、比例、对称性和抛光会共同影响视觉表现与市场评价，具体价值还会随品种与市场变化。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>切工</th><th>备注</th></tr></thead><tbody><tr><td>钻石</td><td>祖母绿阶梯切</td><td>历史与审美示例</td></tr><tr><td>钻石</td><td>公主方切工</td><td>现代方形轮廓示例</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/gia-news-research-value-factors-gem-cutting-styles-definitions" target="_blank" rel="noreferrer">GIA：宝石切工风格定义</a><span>轮廓、刻面排列、阶梯式、蛋面与雕刻等切工风格的定义</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA：有色宝石价值要素与切工质量</a><span>比例、对称性、抛光、原石限制与视觉表现之间的切工取舍</span><small>打开来源 ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-cut/" target="_blank" rel="noreferrer">GIA：钻石切工与明亮度</a><span>圆明亮式的台面、冠部、腰棱、亭部，以及 57/58 面计数说明</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/emerald-quality-factor" target="_blank" rel="noreferrer">GIA：祖母绿质量要素</a><span>有色宝石切割对颜色、耐久性、包裹体与裂隙的综合考量</span><small>打开来源 ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-fancy-cuts-zh"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-fancy-cuts-zh">本页证据映射</h2><p class="gem-reference-block__intro">把本页的教学主张映射到来源，并标注它在知识库中的证据状态。</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">来源支持</strong><span>花式切工通常同时涉及非圆轮廓与具体刻面排列，不能只按外轮廓理解。</span><small>GIA：宝石切工风格定义</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">教学归纳</strong><span>花式切工的市场评价受品种、比例、对称性、抛光与需求共同影响。</span><small>GIA：有色宝石价值要素与切工质量</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">教学归纳</strong><span>教学案例用轮廓、刻面、对称性和观察条件共同比较花式切工。</span><small>GIA：宝石切工风格定义；GIA：有色宝石价值要素与切工质量</small></li></ul></aside><p><em>详见<a href="./intro.html">切割总览</a>。</em></p>',17))])}const g=l(o,[["render",c]]);export{f as __pageData,g as default};
